/**
 * Determines whether an automatic row limit should be appended to a SQL query.
 *
 * An auto limit is only appended for a single, simple SELECT statement that does
 * not already specify a limit and does not contain line comments.
 */
export function checkIfAppendLimitRequired(sql: string, limit: number) {
  const cleanedSql = sql.trim()

  // Split into statements to ensure we only deal with a single statement
  const statements = cleanedSql.split(';').filter((x) => x.trim().length > 0)

  const isSingleStatement = statements.length === 1
  const isSelect = /^select\b/i.test(cleanedSql)
  const containsLimit = /\blimit\b/i.test(cleanedSql)
  const containsComment = cleanedSql.includes('--')

  const appendAutoLimit =
    limit > 0 && isSingleStatement && isSelect && !containsLimit && !containsComment

  return { appendAutoLimit }
}

/**
 * Appends a `limit {n}` clause to a SQL string, stripping any trailing
 * semicolons first and ensuring the result ends with exactly one semicolon.
 */
export function suffixWithLimit(sql: string, limit: number) {
  const withoutTrailingSemicolons = sql.replace(/[;\s]+$/, '')
  return `${withoutTrailingSemicolons} limit ${limit};`
